/**
 * Scenario: on a tiny auto-grow map the startup domain publication hits MAP_FULL and releases its writer; before it
 * asks for growth a user write is admitted and owns the growth episode. Startup maintenance cannot replace that writer,
 * so it must wait for it and then retry the complete publication, not give up for this process.
 */
@Timeout(90)
class LmdbDeferredDomainStartupWriterOverlapTest {
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI SUBJECT = VF.createIRI("urn:startup-domain:subject");
	private static final IRI PREDICATE = VF.createIRI("urn:startup-domain:predicate");
	private static final Literal CANONICAL = VF.createLiteral("7", XSD.INT);
	private static final String POST_READY = "LmdbStore-PostReady";

	private static LmdbStoreConfig config(long mapBytes) {
		return new LmdbStoreConfig("spoc,posc").setForceSync(true).setTripleDBSize(mapBytes);
	}

	@Test
	void startupDomainPublicationWaitsForAnAdmittedWriterAndRetriesAfterCapacityFailure(
			@TempDir(cleanup = CleanupMode.NEVER) Path directory) throws Exception {
		CountDownLatch domainParked = new CountDownLatch(1);
		CountDownLatch releaseDomain = new CountDownLatch(1);
		CountDownLatch userParked = new CountDownLatch(1);
		CountDownLatch releaseUser = new CountDownLatch(1);
		AtomicBoolean domainHookUsed = new AtomicBoolean();
		AtomicBoolean userHookUsed = new AtomicBoolean();
		LmdbStore store = new LmdbStore(directory.toFile(), config(1L)) {
			@Override
			LmdbSailStore createBackingStore(File dataDir, StoreProperties properties, LmdbStoreConfig config,
					boolean estimatorEnabled) throws IOException, SailException {
				return new LmdbSailStore(dataDir, properties, config, estimatorEnabled,
						(valueDir, valueProperties, valueConfig) -> new ValueStore(valueDir, valueProperties,
								valueConfig),
						(tripleDir, tripleProperties, tripleConfig, values) -> new TripleStore(tripleDir,
								tripleProperties, tripleConfig, values) {
							@Override
							boolean growMapForEstimatedWrite(long estimatedWriteBytes,
									LmdbSailStore.MapGrowthAttempt growthAttempt) throws IOException {
								if (Thread.currentThread().getName().equals("domain-overlap-user")
										&& userHookUsed.compareAndSet(false, true)) {
									// The user's own growth episode is open and the user is the admitted writer.
									userParked.countDown();
									await(releaseUser);
								}
								return super.growMapForEstimatedWrite(estimatedWriteBytes, growthAttempt);
							}
						}) {
					@Override
					void completeWriterRollback(Object owner) {
						super.completeWriterRollback(owner);
						if (Thread.currentThread().getName().equals(POST_READY)
								&& getTripleStore().hasDeferredRdfTermDomainStartup()
								&& domainHookUsed.compareAndSet(false, true)) {
							// The failed deferred-domain attempt has closed and released its writer lease, but the
							// loop has not yet reached its grow-or-rethrow decision.
							domainParked.countDown();
							await(releaseDomain);
						}
					}
				};
			}
		};
		ExecutorService executor = Executors
				.newSingleThreadExecutor(runnable -> new Thread(runnable, "domain-overlap-user"));
		try {
			store.init();
			assertTrue(domainParked.await(30, TimeUnit.SECONDS), "post-ready deferred-domain attempt never failed");
			Future<?> user = executor.submit(() -> {
				try (SailConnection connection = store.getConnection()) {
					connection.begin(IsolationLevels.SNAPSHOT);
					connection.addStatement(SUBJECT, PREDICATE, CANONICAL);
					connection.commit();
				}
				return null;
			});
			assertTrue(userParked.await(30, TimeUnit.SECONDS), "the user write never reached its own map growth");
			releaseDomain.countDown();
			// Deterministic, sleep-free ordering: the post-ready thread either ends (current behaviour) or blocks
			// waiting for the admitted writer; only then may the user write finish.
			awaitPostReadyEndedOrWaiting();
			releaseUser.countDown();
			user.get(30, TimeUnit.SECONDS);
			LmdbTestUtil.awaitPostReadyInitialization(store, 30, TimeUnit.SECONDS);
			assertFalse(store.getBackingStore().getTripleStore().hasDeferredRdfTermDomainStartup(),
					"the deferred domain work must be published once the user write has finished");
		} finally {
			releaseDomain.countDown();
			releaseUser.countDown();
			executor.shutdownNow();
			store.shutDown();
		}
	}

	/**
	 * Scenario: growth is refused because a user writer holds an open write transaction (no growth episode exists, so
	 * emergency growth is admitted but returns false). Two different user writers hold the transaction in turn while
	 * the startup publication keeps hitting MAP_FULL; each must be waited for, and the publication then completes.
	 */
	@Test
	void startupDomainPublicationWaitsForEveryWriterHoldingAWriteTransactionWhenGrowthIsRefused(
			@TempDir(cleanup = CleanupMode.NEVER) Path directory) throws Exception {
		CountDownLatch[] domainParked = { new CountDownLatch(1), new CountDownLatch(1) };
		CountDownLatch[] releaseDomain = { new CountDownLatch(1), new CountDownLatch(1) };
		CountDownLatch[] userParked = { new CountDownLatch(1), new CountDownLatch(1) };
		CountDownLatch[] releaseUser = { new CountDownLatch(1), new CountDownLatch(1) };
		AtomicInteger domainParks = new AtomicInteger();
		AtomicInteger userParks = new AtomicInteger();
		AtomicInteger injectedFaults = new AtomicInteger();
		LmdbStore store = new LmdbStore(directory.toFile(), config(8L * 1024L * 1024L)) {
			@Override
			LmdbSailStore createBackingStore(File dataDir, StoreProperties properties, LmdbStoreConfig config,
					boolean estimatorEnabled) throws IOException, SailException {
				return new LmdbSailStore(dataDir, properties, config, estimatorEnabled,
						(valueDir, valueProperties, valueConfig) -> new ValueStore(valueDir, valueProperties,
								valueConfig),
						(tripleDir, tripleProperties, tripleConfig, values) -> new TripleStore(tripleDir,
								tripleProperties, tripleConfig, values) {
							@Override
							int commitDeferredDomainNativeWriter(long transaction,
									RetirementNativeTransaction nativeOwner) throws IOException {
								// The first two domain commits report a full map without it being full.
								if (injectedFaults.getAndIncrement() < 2) {
									nativeOwner.abort();
									return MDB_MAP_FULL;
								}
								return super.commitDeferredDomainNativeWriter(transaction, nativeOwner);
							}

							@Override
							void startTransaction(TxnReplayPolicy.Decision decision) throws IOException {
								super.startTransaction(decision);
								if (Thread.currentThread().getName().equals("domain-overlap-user")) {
									int index = userParks.getAndIncrement();
									if (index < 2) {
										// The user's native write transaction is open and its writer is admitted.
										userParked[index].countDown();
										await(releaseUser[index]);
									}
								}
							}
						}) {
					@Override
					void completeWriterRollback(Object owner) {
						super.completeWriterRollback(owner);
						if (Thread.currentThread().getName().equals(POST_READY)
								&& getTripleStore().hasDeferredRdfTermDomainStartup() && injectedFaults.get() > 0) {
							int index = domainParks.getAndIncrement();
							if (index < 2) {
								domainParked[index].countDown();
								await(releaseDomain[index]);
							}
						}
					}
				};
			}
		};
		ExecutorService executor = Executors.newSingleThreadExecutor(runnable -> new Thread(runnable,
				"domain-overlap-user"));
		try {
			store.init();
			for (int round = 0; round < 2; round++) {
				assertTrue(awaitLatchOrPostReadyEnd(domainParked[round]),
						"startup publication ended instead of retrying (round " + round + ")");
				int writeNumber = round;
				Future<?> user = executor.submit(() -> {
					try (SailConnection connection = store.getConnection()) {
						connection.begin(IsolationLevels.SNAPSHOT);
						connection.addStatement(SUBJECT, PREDICATE, VF.createLiteral("write-" + writeNumber));
						connection.commit();
					}
					return null;
				});
				assertTrue(userParked[round].await(30, TimeUnit.SECONDS),
						"the user write never opened its write transaction");
				releaseDomain[round].countDown();
				awaitPostReadyEndedOrWaiting();
				releaseUser[round].countDown();
				user.get(30, TimeUnit.SECONDS);
			}
			LmdbTestUtil.awaitPostReadyInitialization(store, 30, TimeUnit.SECONDS);
			assertFalse(store.getBackingStore().getTripleStore().hasDeferredRdfTermDomainStartup(),
					"the deferred domain work must be published once both user writes have finished");
		} finally {
			for (int i = 0; i < 2; i++) {
				releaseDomain[i].countDown();
				releaseUser[i].countDown();
			}
			executor.shutdownNow();
			store.shutDown();
		}
	}

	/** Bounded state poll (no sleep) for a latch that the post-ready thread trips, or the end of that thread. */
	private static boolean awaitLatchOrPostReadyEnd(CountDownLatch latch) {
		long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(30);
		while (System.nanoTime() < deadline) {
			if (latch.getCount() == 0) {
				return true;
			}
			boolean alive = false;
			for (Thread candidate : Thread.getAllStackTraces().keySet()) {
				if (candidate.getName().equals(POST_READY) && candidate.isAlive()) {
					alive = true;
				}
			}
			if (!alive) {
				return latch.getCount() == 0;
			}
			Thread.onSpinWait();
		}
		return false;
	}

	/**
	 * Bounded state poll (no sleep). No test seam fires when the post-ready thread starts waiting for the writer:
	 * beforeWriterAuthorityPromotion runs only after that wait, beforeWriterAuthorityRelease is on the releasing side,
	 * afterAttemptAdmissionWaitStarted covers attempt admission, not the writer-owner wait.
	 */
	private static void awaitPostReadyEndedOrWaiting() {
		long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(30);
		while (System.nanoTime() < deadline) {
			Thread worker = null;
			for (Thread candidate : Thread.getAllStackTraces().keySet()) {
				if (candidate.getName().equals(POST_READY)) {
					worker = candidate;
				}
			}
			if (worker == null || !worker.isAlive()) {
				return;
			}
			Thread.State state = worker.getState();
			if (state == Thread.State.WAITING || state == Thread.State.TIMED_WAITING) {
				for (StackTraceElement frame : worker.getStackTrace()) {
					String name = frame.getClassName() + "." + frame.getMethodName();
					if (name.contains("MapGrowthCoordinator") || name.contains("acquireWriterLease")) {
						return;
					}
				}
			}
			Thread.onSpinWait();
		}
		throw new AssertionError("post-ready thread neither ended nor waited for the admitted writer");
	}

	private static void await(CountDownLatch latch) {
		try {
			if (!latch.await(60, TimeUnit.SECONDS)) {
				throw new IllegalStateException("test latch was never released");
			}
		} catch (InterruptedException interrupted) {
			Thread.currentThread().interrupt();
			throw new IllegalStateException(interrupted);
		}
	}
}
